import itertools
t=df['t'];P=df['P'];y=df['dP_dt'];V=np.var(y)
F={'1':np.ones_like(t),'t':t,'t2':t**2,'sqrtt':np.sqrt(t),'logt':np.log(t),'expt':np.exp(-t),'cost':np.cos(t),'sint':np.sin(t),
