terms={}
for a,b in itertools.combinations_with_replacement(F.keys(),2):
    terms[f'{a}*{b}']=F[a]*F[b]
names=list(terms.keys())
M=np.column_stack([terms[n] for n in names])
res=[]
for c in np.linspace(0.1,2,191):
    r0=y-c*np.sin(c*t)*P
