        X=M[:,[i,j]]
        b=np.linalg.lstsq(X,r0,rcond=None)[0]
        e=np.mean((X@b-r0)**2)/V
        res.append((e,round(c,3),names[i],names[j],b.round(4)))
res.sort(key=lambda x:x[0])
